const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, LevelFormat,
  BorderStyle, TabStopType, TabStopPosition
} = require("docx");

const NAVY = "1F3A5F";
const GOLD = "B0894F";
const GRAY = "5F5F5F";
const CW = 9360; // content width, US Letter, 1in margins

// ---------- helpers ----------
const bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 60 },
  children: [new TextRun({ text, size: 22, font: "Arial" })],
});

const label = (text) => new Paragraph({
  spacing: { before: 120, after: 60 },
  children: [new TextRun({ text, bold: true, size: 22, font: "Arial", color: NAVY })],
});

const tagline = (text) => new Paragraph({
  spacing: { after: 100 },
  children: [new TextRun({ text, italics: true, size: 22, font: "Arial", color: GRAY })],
});

const valueLine = (text) => new Paragraph({
  spacing: { before: 100, after: 200 },
  children: [new TextRun({ text, bold: true, size: 22, font: "Arial", color: NAVY })],
});

const body = (text, opts = {}) => new Paragraph({
  spacing: { after: opts.after ?? 120 },
  alignment: opts.center ? AlignmentType.CENTER : AlignmentType.LEFT,
  children: [new TextRun({ text, size: opts.size ?? 22, font: "Arial", color: opts.color ?? "333333", italics: !!opts.italics, bold: !!opts.bold })],
});

const namePrice = (name, price) => new Paragraph({
  tabStops: [{ type: TabStopType.RIGHT, position: CW }],
  spacing: { before: 320, after: 60 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 4 } },
  children: [
    new TextRun({ text: name, bold: true, size: 34, font: "Georgia", color: NAVY }),
    new TextRun({ text: "\t" + price, bold: true, size: 28, font: "Georgia", color: NAVY }),
  ],
});

const sectionHeader = (text) => new Paragraph({
  spacing: { before: 400, after: 160 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: NAVY, space: 4 } },
  children: [new TextRun({ text, bold: true, size: 30, font: "Georgia", color: NAVY })],
});

const priceRow = (left, right) => new Paragraph({
  tabStops: [{ type: TabStopType.RIGHT, position: CW }],
  spacing: { after: 60 },
  children: [
    new TextRun({ text: left, size: 22, font: "Arial", color: "333333" }),
    new TextRun({ text: "\t" + right, size: 22, font: "Arial", bold: true, color: NAVY }),
  ],
});

function titleBlock(subtitle, intro) {
  return [
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 40 },
      children: [new TextRun({ text: "Belle Aesthetics", bold: true, size: 52, font: "Georgia", color: NAVY })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 40 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 6 } },
      children: [new TextRun({ text: subtitle, size: 30, font: "Georgia", color: NAVY, italics: true })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 200 },
      children: [new TextRun({ text: intro, size: 22, font: "Arial", color: GRAY, italics: true })] }),
  ];
}

const docDefaults = {
  styles: { default: { document: { run: { font: "Arial", size: 22 } } } },
  numbering: { config: [
    { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022",
      alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 540, hanging: 260 } } } }] },
  ] },
};

const pageProps = { properties: { page: { size: { width: 12240, height: 15840 },
  margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 } } } };

// ============ MEMBERSHIP DOC ============
const tiers = [
  { name: "The Glow Up", price: "$99 / month",
    tag: "Your monthly reset. Everyday maintenance and natural radiance.",
    chooseLabel: "Choose one signature treatment each month:",
    choices: ["Mini Skin Treatment", "Express Chemical Peel", "Dermaplane", "Microdermabrasion",
      "A 30 minute Red Light Therapy session with a scalp massage add on"],
    receiveLabel: "Every month you also receive:",
    receive: [
      "Member tox pricing at $11.50 per unit",
      "10 percent savings on filler and all injectables",
      "10 percent savings on all medical grade skincare and retail",
      "10 percent savings on all treatments and add ons",
      "Beauty Bank: any signature treatment value you do not use banks for 12 months",
      "A birthday treatment gift and one guest pass each quarter"],
    value: "Estimated value: up to $150 every month, for $99." },
  { name: "The Belle of the Ball", price: "$199 / month",
    tag: "Visible results and active collagen building. Most popular.",
    chooseLabel: "Choose one signature treatment each month:",
    choices: ["Glo2 Oxygen Skin Treatment", "Customized Skin Treatment",
      "Lash Lift and Tint with a brow add on", "Laser hair removal, one small or medium single area"],
    receiveLabel: "Every month you also receive:",
    receive: [
      "A $25 Beauty Bank bonus credit toward any service",
      "Member tox pricing at $11.25 per unit",
      "15 percent savings on filler and all injectables",
      "15 percent savings on all medical grade skincare and retail",
      "15 percent savings on all treatments",
      "Beauty Bank rollover, priority booking, and one guest pass each quarter",
      "One complimentary seasonal add on each quarter: red light, brow, or lip"],
    value: "Estimated value: $250 or more every month, for $199." },
  { name: "The Showstopper", price: "$299 / month",
    tag: "Advanced resurfacing and collagen remodeling.",
    chooseLabel: "Choose one signature treatment each month, or bank the full value:",
    choices: ["Procell Microchanneling", "Glo2 Oxygen with Chemical Peel", "VI Chemical Peel",
      "RF Microneedling, Neck", "Bank the full monthly value toward RF Microneedling Face and Neck"],
    receiveLabel: "Every month you also receive:",
    receive: [
      "A $50 Beauty Bank bonus credit toward any service",
      "Member tox pricing at $11.00 per unit",
      "20 percent savings on filler and all injectables",
      "20 percent savings on all medical grade skincare and retail",
      "20 percent savings on all treatments",
      "Beauty Bank rollover, priority booking, and two guest passes each quarter",
      "One complimentary express treatment each quarter and an annual loyalty gift"],
    value: "Estimated value: $450 or more every month, for $299." },
  { name: "The Forever Belle VIP", price: "$499 / month",
    tag: "Concierge access. The highest level of savings and care at Belle.",
    chooseLabel: "Choose two signature treatments each month, or take one and bank the rest:",
    choices: [
      "Any two from Procell Microchanneling, Glo2 with Chemical Peel, VI Chemical Peel, RF Microneedling single area, and signature facials",
      "Take one selection and bank the remaining value toward anything, including RF Microneedling Face and Neck"],
    receiveLabel: "Your VIP privileges every month:",
    receive: [
      "A $100 Beauty Bank bonus credit, the most generous offered, applied to anything",
      "25 percent savings on all treatments and injectables, the deepest in the practice",
      "20 percent savings on all medical grade skincare and retail",
      "Member tox pricing at $10.50 per unit, the lowest rate offered",
      "Member filler pricing, the lowest per syringe rate offered",
      "A dedicated concierge line and same week priority scheduling",
      "First access to new technology, events, and limited appointment windows",
      "One complimentary signature treatment each quarter, on top of your monthly selections",
      "An annual VIP treatment credit, for example a complimentary Procell Microchanneling session",
      "Complimentary numbing and aftercare, no booking fees, and four guest passes per year",
      "Invitations to private VIP events, plus premium birthday and anniversary gifts"],
    value: "Estimated value: $900 or more every month, for $499." },
];

const memberChildren = [];
memberChildren.push(...titleBlock("The Membership Collection",
  "Every membership includes a signature treatment of your choice each month, member pricing across the entire menu, and a Beauty Bank, so no value is ever lost."));
for (const t of tiers) {
  memberChildren.push(namePrice(t.name, t.price));
  memberChildren.push(tagline(t.tag));
  memberChildren.push(label(t.chooseLabel));
  t.choices.forEach(c => memberChildren.push(bullet(c)));
  memberChildren.push(label(t.receiveLabel));
  t.receive.forEach(r => memberChildren.push(bullet(r)));
  memberChildren.push(valueLine(t.value));
}
memberChildren.push(sectionHeader("How Your Membership Works"));
memberChildren.push(body("Your monthly fee includes your signature treatment of choice and unlocks member pricing across the entire menu. If you do not use your signature treatment in a given month, its value banks automatically in your Beauty Bank and stays available for 12 months, so your investment is never lost. Bonus credits bank and roll over the same way."));
memberChildren.push(body("Beauty Bank value may be applied toward any service. It is not redeemable for cash and does not combine with other promotions."));
memberChildren.push(body("Memberships begin with a three month commitment, then continue month to month. You may upgrade, downgrade, or pause anytime after the first three months. Member pricing reflects standard rates and cannot be combined with other promotions. Treatment selections and values are illustrative and confirmed at booking."));
memberChildren.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 240 },
  children: [new TextRun({ text: "Ready to join? Speak with your provider or our front desk today.", bold: true, size: 24, font: "Georgia", color: NAVY })] }));

const memberDoc = new Document({ ...docDefaults, sections: [{ ...pageProps, children: memberChildren }] });

// ============ PACKAGES DOC ============
const journeys = [
  { name: "Glass Skin Reset", price: "$1,399", tag: "Clear, refined, and lit from within.",
    included: ["Procell Microchanneling, a series of 4", "Express Chemical Peel, a series of 4"],
    value: "\u00C0 la carte value $2,120. You save $721, about 34 percent.",
    why: "Microchanneling drives active serums deep and triggers new collagen, while the peels keep the surface bright between sessions, so tone and texture improve together." },
  { name: "Snatched and Sculpted", price: "$2,999", tag: "Our most powerful non surgical tightening.",
    included: ["RF Microneedling Face and Neck, a series of 4"],
    value: "\u00C0 la carte value $4,000. You save $1,001, about 25 percent.",
    why: "Radiofrequency energy remodels collagen deep in the skin while microneedling refines the surface, firming the jawline and neck across the series." },
  { name: "Red Carpet Ready", price: "$1,599", tag: "Camera ready radiance for an event, a season, or a reset.",
    included: ["Glo2 Oxygen with Chemical Peel, a series of 3", "25 units of tox", "One syringe of filler", "One Dermaplane finish"],
    value: "\u00C0 la carte value $1,877. You save $278, about 15 percent.",
    why: "Every step is low downtime and high impact, sequenced so your skin peaks right when you need it." },
  { name: "The Full Send", price: "$1,799", tag: "Balanced, refreshed, and naturally lifted.",
    included: ["100 units of tox", "One full syringe of filler"],
    value: "\u00C0 la carte value $2,075. You save $276, about 13 percent.",
    why: "Tox softens movement while filler restores structure. Together they balance the whole face rather than chasing one line at a time." },
  { name: "Soft Launch", price: "$799", tag: "A first step into tox and filler, beautifully subtle.",
    included: ["50 units of tox", "One half syringe of filler"],
    value: "\u00C0 la carte value $1,050. You save $251, about 24 percent.",
    why: "A lighter touch for first timers or easy maintenance, enough to refresh without overdoing it." },
];

const pkgChildren = [];
pkgChildren.push(...titleBlock("Signature Packages",
  "Each package combines our most effective treatments toward one outcome, at one bundled investment below the \u00E0 la carte menu."));

pkgChildren.push(sectionHeader("Signature Journeys"));
for (const j of journeys) {
  pkgChildren.push(namePrice(j.name, j.price));
  pkgChildren.push(tagline(j.tag));
  pkgChildren.push(label("What is included:"));
  j.included.forEach(i => pkgChildren.push(bullet(i)));
  pkgChildren.push(valueLine(j.value));
  pkgChildren.push(new Paragraph({ spacing: { after: 160 },
    children: [new TextRun({ text: "Why it works: ", italics: true, bold: true, size: 22, font: "Arial", color: GRAY }),
      new TextRun({ text: j.why, italics: true, size: 22, font: "Arial", color: GRAY })] }));
}

pkgChildren.push(sectionHeader("Treatment Series"));
pkgChildren.push(label("Skin and Facial Series"));
[["4 Procell Microchanneling", "$1,440  (save $360)"],
 ["4 Glo2 Oxygen Facials", "$756  (save $40)"],
 ["4 Glo2 Oxygen with Chemical Peel", "$960  (save $40)"],
 ["Glo2 with Chemical Peel, buy 5 get 1 free", "$1,250  (save $250)"],
 ["3 Express Chemical Peels", "$195  (save $45)"],
 ["3 VI Chemical Peels", "$895  (save $155)"],
 ["3 RF Microneedling Face and Neck", "$2,750  (save $250)"]].forEach(r => pkgChildren.push(priceRow(r[0], r[1])));

pkgChildren.push(label("Laser Hair Removal Series  (buy 6, get the 7th free)"));
[["Underarms", "$480"], ["Bikini", "$540"], ["Brazilian", "$900"], ["Small", "$300"],
 ["Full Legs", "$1,950"], ["Half Legs", "$1,200"], ["Full Arms", "$1,380"], ["Forearms", "$750"],
 ["Full Face", "$900"], ["Brazilian and Underarms combo, 7 each plus free maintenance", "$999"]
].forEach(r => pkgChildren.push(priceRow(r[0], r[1])));

pkgChildren.push(label("Waxing Series"));
[["3 Bikini", "$135  (save $15)"], ["3 Brazilian Maintenance", "$195  (save $30)"],
 ["3 Full Legs", "$180  (save $30)"], ["3 Back", "$165  (save $30)"]
].forEach(r => pkgChildren.push(priceRow(r[0], r[1])));

pkgChildren.push(label("Quick Bundles"));
pkgChildren.push(priceRow("The Lunchtime Glow: Dermaplane or Microdermabrasion, Express Peel or Enzyme, plus 25 minute Red Light", "$99"));
pkgChildren.push(body("About a $190 value.", { italics: true, color: GRAY, size: 20, after: 100 }));
pkgChildren.push(priceRow("Even and Bright: 3 sessions of Customized Corrective Skin Treatment, Express Peel, plus 25 minute Red Light", "$599"));
pkgChildren.push(body("\u00C0 la carte value $780. You save $181, about 23 percent.", { italics: true, color: GRAY, size: 20, after: 120 }));

// Signature Year
pkgChildren.push(sectionHeader("The Belle Signature Year"));
pkgChildren.push(new Paragraph({ spacing: { after: 60 },
  children: [new TextRun({ text: "$8,400 for the year, or just $700 per month", bold: true, size: 26, font: "Georgia", color: NAVY })] }));
pkgChildren.push(tagline("Our most complete transformation, guided across twelve months and sequenced so each result builds on the next."));

const quarters = [
  ["Quarter 1, Foundation and Reset", [
    "Procell Microchanneling series begins, four sessions",
    "A baseline assessment and your custom medical grade skincare regimen",
    "Your monthly signature facials begin"]],
  ["Quarter 2, Resurface and Refine", [
    "RF Microneedling Face and Neck, a series of 3",
    "Monthly facials continue",
    "A quarterly tox refresh"]],
  ["Quarter 3, Smooth and Define", [
    "Laser hair removal, Brazilian and underarms series",
    "One syringe of dermal filler",
    "A quarterly tox refresh"]],
  ["Quarter 4, Reveal", [
    "A VI Chemical Peel and a final Procell polish",
    "A second syringe of filler as needed",
    "A professional before and after reveal session"]],
];
for (const [q, items] of quarters) {
  pkgChildren.push(label(q));
  items.forEach(i => pkgChildren.push(bullet(i)));
}
pkgChildren.push(label("Included every month, all year"));
["A signature facial every month",
 "Quarterly tox touch ups to stay refreshed year round",
 "Your medical grade skincare regimen, replenished each quarter",
 "Priority booking and first access to new technology"].forEach(i => pkgChildren.push(bullet(i)));
pkgChildren.push(valueLine("\u00C0 la carte value $12,780. Your investment $8,400. You save $4,380, about 34 percent."));
pkgChildren.push(body("Twelve monthly payments of $700, with no large payment up front. Financing available."));
pkgChildren.push(body("Optional add on: a medical weight loss and wellness track can be layered into the year at consultation.", { italics: true, color: GRAY }));
pkgChildren.push(new Paragraph({ spacing: { after: 160 },
  children: [new TextRun({ text: "Why it works: ", italics: true, bold: true, size: 22, font: "Arial", color: GRAY }),
    new TextRun({ text: "It is weighted toward high margin, recurring treatments with the device work spread across the year, so it delivers the deepest savings we offer in exchange for a full year commitment.", italics: true, size: 22, font: "Arial", color: GRAY })] }));

pkgChildren.push(sectionHeader("Good to Know"));
pkgChildren.push(body("Packages are already priced below the \u00E0 la carte menu and do not combine with membership percentage discounts. Members may apply Beauty Bank credit toward any package."));
pkgChildren.push(body("\u00C0 la carte values are drawn from the current Belle Aesthetics menu, and every bundle is priced against treatment margin, so each package protects profit."));
pkgChildren.push(body("Treatment plans are personalized at consultation and adjusted for candidacy and goals. Areas shown are examples and may be substituted for equivalent value."));
pkgChildren.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 240 },
  children: [new TextRun({ text: "Ready to begin? Book your complimentary consultation today.", bold: true, size: 24, font: "Georgia", color: NAVY })] }));

const pkgDoc = new Document({ ...docDefaults, sections: [{ ...pageProps, children: pkgChildren }] });

// ---------- write ----------
(async () => {
  const m = await Packer.toBuffer(memberDoc);
  fs.writeFileSync("/mnt/user-data/outputs/Belle_Aesthetics_Membership_Collection.docx", m);
  const p = await Packer.toBuffer(pkgDoc);
  fs.writeFileSync("/mnt/user-data/outputs/Belle_Aesthetics_Signature_Packages.docx", p);
  console.log("done");
})();

