const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, LevelFormat,
  BorderStyle, TabStopType, WidthType, Table, TableRow, TableCell, ShadingType
} = require("docx");

const NAVY = "1F3A5F";
const GOLD = "B0894F";
const GRAY = "5F5F5F";
const LIGHT = "F2EFE9";
const CW = 9360;

const bullet = (text, bold) => new Paragraph({
  numbering: { reference: "bullets2", level: 0 }, spacing: { after: 80 },
  children: bold
    ? [new TextRun({ text: bold + " ", bold: true, size: 22, font: "Arial", color: NAVY }), new TextRun({ text, size: 22, font: "Arial" })]
    : [new TextRun({ text, size: 22, font: "Arial" })],
});
const label = (text) => new Paragraph({ spacing: { before: 160, after: 60 },
  children: [new TextRun({ text, bold: true, size: 23, font: "Arial", color: NAVY })] });
const body = (text, opts = {}) => new Paragraph({ spacing: { after: opts.after ?? 140 },
  alignment: opts.center ? AlignmentType.CENTER : AlignmentType.LEFT,
  children: [new TextRun({ text, size: opts.size ?? 22, font: "Arial", color: opts.color ?? "333333", italics: !!opts.italics, bold: !!opts.bold })] });
const say = (text) => new Paragraph({ spacing: { after: 140 },
  indent: { left: 360 }, border: { left: { style: BorderStyle.SINGLE, size: 18, color: GOLD, space: 12 } },
  children: [new TextRun({ text, size: 22, font: "Arial", color: "2A2A2A", italics: true })] });
const sectionHeader = (text) => new Paragraph({ spacing: { before: 420, after: 160 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: NAVY, space: 4 } },
  children: [new TextRun({ text, bold: true, size: 30, font: "Georgia", color: NAVY })] });

function titleBlock(subtitle, intro) {
  return [
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 40 },
      children: [new TextRun({ text: "Belle Aesthetics", bold: true, size: 52, font: "Georgia", color: NAVY })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 40 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 6 } },
      children: [new TextRun({ text: subtitle, size: 30, font: "Georgia", color: NAVY, italics: true })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 200 },
      children: [new TextRun({ text: intro, size: 22, font: "Arial", color: GRAY, italics: true })] }),
  ];
}
const cell = (text, opts = {}) => new TableCell({
  width: { size: opts.w, type: WidthType.PERCENTAGE },
  shading: opts.head ? { type: ShadingType.CLEAR, fill: NAVY } : (opts.alt ? { type: ShadingType.CLEAR, fill: LIGHT } : undefined),
  margins: { top: 80, bottom: 80, left: 120, right: 120 },
  children: [new Paragraph({ children: [new TextRun({ text, bold: !!opts.head, size: 21, font: "Arial", color: opts.head ? "FFFFFF" : "333333" })] })],
});

const docDefaults = { styles: { default: { document: { run: { font: "Arial", size: 22 } } } },
  numbering: { config: [{ reference: "bullets2", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022",
    alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 540, hanging: 260 } } } }] }] } };
const pageProps = { properties: { page: { size: { width: 12240, height: 15840 },
  margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 } } } };

const C = [];
C.push(...titleBlock("The Membership and Package Strategy",
  "Why it is built this way, the numbers behind it, and the words to get every client onto at least one offer."));

// PART 1
C.push(sectionHeader("Part 1. What You Say to the Owner"));
C.push(body("This is your talk track. Say it in your own voice. The lines in the margin are meant to be spoken almost as written.", { italics: true, color: GRAY }));
C.push(say("Here is the thinking behind what I built for you, and why it is going to change how your practice makes money. Right now most of your revenue is transactional. Someone comes in, pays, and leaves, and you hope they come back. That means your income swings with the seasons and you are paying over and over to win back the same clients. This structure flips that. We are turning one-time visits into predictable monthly revenue, and turning your best clients into members who stay for years."));
C.push(say("The data on this is not subtle. Med spas with real membership programs pull twenty to forty percent of their revenue from recurring sources. A hundred members at around two hundred dollars a month is roughly two hundred thirty-eight thousand dollars a year you can count on before anyone books a single extra treatment."));
C.push(say("And members are worth far more than walk-ins. They carry about three times the lifetime value, they come in nearly three times as often, and they spend about thirty-five percent more per visit. Industry data shows each member adds over eleven hundred dollars a year in extra spending, with tox sales up around thirty-one percent and filler up around forty-three percent once they join. The average ticket at a membership spa is about forty percent higher than at a non-member spa."));
C.push(say("Here is why the Beauty Bank matters. When the monthly fee banks instead of vanishing, the client never feels like they are losing money, so they stay. Members are about seventy-eight percent less likely to switch providers. In one case, when a competitor opened nearby, only three percent of members left, compared to thirty-one percent of non-members. The bank is not a giveaway, it is a loyalty lock."));
C.push(say("The four tiers are deliberate. The Glow Up at ninety-nine dollars is a low-friction front door that removes price as an excuse. The Forever Belle at four ninety-nine sets a high anchor that makes the middle tiers feel easy, and it captures your highest spenders. Most people land in the middle, which is exactly where we want them."));
C.push(say("And every discount is calibrated to protect your margin. Injectables run fifty to seventy percent margins, so a member discount there is safe. Skincare and retail are your thinnest margin, so those discounts cap at twenty percent. Tox has a price floor so it never sells below cost. Packages do not stack on membership pricing. Nothing in here sells below what it costs you to deliver."));
C.push(say("The packages do something different. They bring cash in the door up front, they raise the average ticket by thirty to fifty percent, and because the client commits to a series they actually finish their plan, which means better results, better reviews, and more referrals. The Signature Year is the deepest commitment and the deepest savings, and it locks a client in for a full twelve months."));
C.push(say("There is one rule that makes or breaks all of it. Members have to spend their credit on high-margin services, not only on tox. If they only burn credit on product and toxin, net margin can slip under fifteen percent. That is exactly why every tier includes a facial or skin treatment as the signature service. We are steering the value toward the treatments that protect your profit."));

// PART 2
C.push(sectionHeader("Part 2. What the Owner Can Make"));
C.push(body("The figures below are illustrative and drawn from current industry benchmarks. Confirm against the practice's own numbers. They show the shape of the opportunity, not a guarantee.", { italics: true, color: GRAY }));
const t = new Table({ width: { size: 100, type: WidthType.PERCENTAGE }, rows: [
  new TableRow({ tableHeader: true, children: [cell("The lever", { w: 34, head: true }), cell("Industry result", { w: 33, head: true }), cell("What it means at 100 members", { w: 33, head: true })] }),
  new TableRow({ children: [cell("Predictable recurring base"), cell("20 to 40 percent of revenue becomes recurring"), cell("About $228,000 a year at a blended $190 per month, before any extra spend", { alt: true })] }),
  new TableRow({ children: [cell("Member lifetime value", { alt: true }), cell("Roughly 3x a walk-in, plus over $1,100 extra spend a year", { alt: true }), cell("About $110,000 in additional annual spend across the base", { alt: true }) ] }),
  new TableRow({ children: [cell("Visit and ticket"), cell("Nearly 3x visit frequency, about 35 percent higher spend, about 40 percent higher ticket"), cell("More chair time filled with your highest-value clients", { alt: true })] }),
  new TableRow({ children: [cell("Injectable lift", { alt: true }), cell("About 31 percent more tox, 43 percent more filler once members", { alt: true }), cell("Captured at 50 to 70 percent injectable margins", { alt: true })] }),
  new TableRow({ children: [cell("Packages"), cell("Raise per-client spend 30 to 50 percent, paid up front"), cell("Each Belle package runs a 49 to 83 percent margin", { alt: true })] }),
] });
C.push(t);
C.push(body("The real prize is not any single number. It is converting a seasonal, transactional practice into a business with predictable monthly cash flow. That stability lets the owner plan, hire, and invest, and it is also what makes a practice worth far more if they ever sell.", { after: 40 }));

// PART 3
C.push(sectionHeader("Part 3. How to Get Every Client on at Least One"));
C.push(body("The menu is built as a ladder, so there is a rung for every client and every budget. The operating rule is simple: no one leaves as a one-off. Every consultation and every checkout ends with the right offer attached to that specific client.", { after: 120 }));
C.push(label("Match the client to the rung"));
C.push(bullet("becomes a member, usually The Belle of the Ball or The Showstopper.", "Loves tox or filler and comes in regularly:"));
C.push(bullet("steer to a package instead, The Full Send or Soft Launch, so they pay once and commit.", "Comes in only now and then for injectables:"));
C.push(bullet("the Glass Skin Reset package, or The Glow Up membership for ongoing care.", "Skin is their main focus:"));
C.push(bullet("Red Carpet Ready for the event, then convert them to a member after.", "Has a wedding, reunion, or milestone:"));
C.push(bullet("The Belle Signature Year, the full twelve-month plan.", "Wants a complete head-to-toe transformation:"));
C.push(bullet("start them on The Lunchtime Glow or The Glow Up, the low-friction front doors that make cost a non-issue.", "Brand new or price-sensitive:"));
C.push(label("The one rule for the team"));
C.push(body("Every client fits somewhere on this ladder. The entry tier and entry bundle exist so that cost is never a reason to walk out empty-handed. If someone truly will not commit today, they leave with the $29 Revenue Leak style mindset, a clear next step and a follow-up booked. Nobody leaves as a pure one-off."));

// PART 4
C.push(sectionHeader("Part 4. The Enrollment Script for the Team"));
C.push(body("This is what your front desk and providers say at the point of sale. Spoken, natural, and built to assume the close.", { italics: true, color: GRAY }));
C.push(label("Step 1. Anchor to what they already do"));
C.push(say("You come in for your tox every few months, and I know you have been loving your facials. Can I show you something that would actually save you money on what you are already doing?"));
C.push(label("Step 2. Make the offer, and reframe the fee"));
C.push(say("We just launched our memberships, and the one that fits you is The Belle of the Ball. It is one ninety-nine a month, but here is the part most people miss. That fee does not disappear. It banks into your Beauty Bank and you spend it on whatever you want, so you are not paying for a membership, you are pre-loading your own treatments. On top of that, you get your tox at eleven twenty-five a unit instead of thirteen fifty, fifteen percent off your filler and your skincare, and you pick a free signature facial every single month."));
C.push(label("Step 3. Remove the risk"));
C.push(say("And there is no risk here. Your money banks for a full year, so you never lose it. After the first three months you can pause, downgrade, or change tiers anytime."));
C.push(label("Step 4. Assume the close"));
C.push(say("Based on what you already come in for, you would more than cover the fee. Want me to set you up today so this visit counts toward it?"));
C.push(label("If they hesitate, here is what you say"));
C.push(say("It feels like a lot per month. Totally fair. We also have The Glow Up at ninety-nine, and remember, the fee banks, so it is really money you are setting aside for treatments you already get."));
C.push(say("I am not sure I will use it every month. That is the best part. Anything you do not use banks for a full twelve months, so it is never lost. It just waits for you."));
C.push(say("I do not want to be locked in. It is only a three-month commitment, then it is month to month. You can pause or drop anytime after that."));
C.push(say("I only come in once in a while. Then a package is smarter for you than a membership. If you are doing tox and a little filler, our Soft Launch saves you about two hundred fifty dollars and you just pay once."));
C.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 320 },
  children: [new TextRun({ text: "Every client leaves on a rung. That is the whole game.", bold: true, size: 24, font: "Georgia", color: NAVY })] }));

const doc = new Document({ ...docDefaults, sections: [{ ...pageProps, children: C }] });
(async () => {
  fs.writeFileSync("/mnt/user-data/outputs/Belle_Aesthetics_Owner_Briefing_and_Scripts.docx", await Packer.toBuffer(doc));
  console.log("done");
})();

