C.push(say("I only come in once in a while. Then a package is smarter for you than a membership. If you are doing tox and a little filler, our Soft Launch saves you about two hundred fifty dollars and you just pay once."));
C.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 320 },
  children: [new TextRun({ text: "Every client leaves on a rung. That is the whole game.", bold: true, size: 24, font: "Georgia", color: NAVY })] }));

const doc = new Document({ ...docDefaults, sections: [{ ...pageProps, children: C }] });
(async () => {
  fs.writeFileSync("/mnt/user-data/outputs/Belle_Aesthetics_Owner_Briefing_and_Scripts.docx", await Packer.toBuffer(doc));
