  children: [new TextRun({ text, bold: true, size: 22, font: "Arial", color: NAVY })] });
const body = (text, o = {}) => new Paragraph({ spacing: { after: o.after ?? 120 }, alignment: o.center ? AlignmentType.CENTER : AlignmentType.LEFT,
  children: [new TextRun({ text, size: o.size ?? 22, font: "Arial", color: o.color ?? "333333", italics: !!o.italics, bold: !!o.bold })] });
