  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 4 } },
  children: [new TextRun({ text: n, bold: true, size: 34, font: "Georgia", color: NAVY }), new TextRun({ text: "\t" + p, bold: true, size: 28, font: "Georgia", color: NAVY })] });
const sectionHeader = (t) => new Paragraph({ spacing: { before: 400, after: 160 }, border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: NAVY, space: 4 } },
